public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());

        int A1 = Integer.parseInt(tokenizer.nextToken());
        int B1 = Integer.parseInt(tokenizer.nextToken());
        int C1 = Integer.parseInt(tokenizer.nextToken());

        tokenizer = new StringTokenizer(reader.readLine());
        int A2 = Integer.parseInt(tokenizer.nextToken());
        int B2 = Integer.parseInt(tokenizer.nextToken());
        int C2 = Integer.parseInt(tokenizer.nextToken());

        System.out.println(judge(A1, B1, C1, A2, B2, C2));
    }

    private static int cross(int a, int b, int c, int d) {
        return a * d - b * c;
    }

    private static boolean zero(int A1, int B1) {
        return A1 * A1 + B1 * B1 == 0;
    }

    private static int lineIntersect(int A1, int B1, int C1, int A2, int B2, int C2) {
        if (cross(A1, B1, A2, B2) == 0) {
            if (cross(A1, C1, A2, C2) == 0 && cross(B1, C1, B2, C2) == 0) {
                return -1;
            } else {
                return 0;
            }
        } else {
            return 1;
        }
    }

    private static int judge(int A1, int B1, int C1, int A2, int B2, int C2) {
        if (zero(A1, B1) && C1 != 0) return 0;
        if (zero(A2, B2) && C2 != 0) return 0;

        if (!zero(A1, B1) && !zero(A2, B2)) {
            return lineIntersect(A1, B1, C1, A2, B2, C2);
        } else {
            return -1;
        }
    }
}

